import json

with open('/app/resources/treasury_bulletin_2011_09.json', 'r') as f:
    data = json.load(f)

# Search for liquidity ratio or U.S. to Foreigners
def search_text(obj, target):
    results = []
    if isinstance(obj, str):
        if target.lower() in obj.lower():
            results.append(obj)
    elif isinstance(obj, dict):
        for v in obj.values():
            results.extend(search_text(v, target))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(search_text(item, target))
    return results

# Search for liquidity ratio
results = search_text(data, 'liquidity ratio')
print(f'Found {len(results)} matches for \"liquidity ratio\"')
for r in results[:5]:
    print(r[:200])

print()
# Search for U.S. to Foreigners
results2 = search_text(data, 'U.S. to Foreigners')
print(f'Found {len(results2)} matches for \"U.S. to Foreigners\"')
for r in results2[:5]:
    print(r[:200])
